import{_ as a,o as e,c as r,a5 as s}from"./chunks/framework.BF53ZjCA.js";const c=JSON.parse('{"title":"物理性质测试","description":"","frontmatter":{"title":"物理性质测试","identification":"physical-tests"},"headers":[],"relativePath":"zh/identification/physical-tests.md","filePath":"zh/identification/physical-tests.md","lastUpdated":1790876393000}'),l={name:"zh/identification/physical-tests.md"};function n(i,t,o,p,d,h){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="物理性质测试" tabindex="-1">物理性质测试 <a class="header-anchor" href="#物理性质测试" aria-label="Permalink to &quot;物理性质测试&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>折射率 (RI)、比重 (SG)、硬度、解理是最基础的鉴定手段——它们由 矿物化学成分与晶体结构影响；同一品种通常落在可比的特征范围， 但测量条件、方向、处理和样品状态都会影响读数。</p><aside class="gem-identification-boundary" aria-labelledby="identification-boundary-physical-tests-zh"><p class="gem-identification-boundary__eyebrow">IDENTIFICATION BOUNDARY</p><h2 id="identification-boundary-physical-tests-zh">边界与安全</h2><p>本页只介绍教育性测试框架，不提供脱离仪器说明、培训和样品条件的操作授权。RI/SG 应记录为典型范围或实测范围，硬度测试可能损伤样品；镶嵌、微小、多孔、易损或高价值样品应跳过不适用测试并考虑送检。 </p></aside><h2 id="鉴定步骤" tabindex="-1">鉴定步骤 <a class="header-anchor" href="#鉴定步骤" aria-label="Permalink to &quot;鉴定步骤&quot;">​</a></h2><p><strong>统一教学协议</strong></p><p>每项测试都按同一顺序阅读：目的 → 适用条件 → 操作与记录 → 结果解释 → 异常处理 → 风险/送检。参考值用于缩小候选范围，不是样品的“密码”。</p><table tabindex="0"><thead><tr><th>测试</th><th>主要输出</th><th>典型限制</th></tr></thead><tbody><tr><td>RI</td><td>单值/范围、方向、读数质量</td><td>弧面、尺寸、透明度、接触状态和量程</td></tr><tr><td>SG</td><td>方法、数值、重复结果</td><td>镶嵌、孔隙、吸液、气泡和样品重量</td></tr><tr><td>莫氏硬度</td><td>是否出现刻划现象</td><td>有损、相对值，不等于真伪或耐久性</td></tr><tr><td>解理</td><td>结构性风险记录</td><td>不通过敲击或劈开验证</td></tr></tbody></table><h3 id="_1-折射率-ri" tabindex="-1">1. 折射率（RI） <a class="header-anchor" href="#_1-折射率-ri" aria-label="Permalink to &quot;1. 折射率（RI）&quot;">​</a></h3><p><strong>目的：</strong> 用折射率和光性信息缩小材料候选范围。</p><p><strong>适用条件：</strong> 先确认折射仪可用，清洁样品和接触面，并判断样品尺寸、弧面和透明度是否适合测量。镶嵌石、过小样品或无法形成可靠接触时，应记录为不适用。</p><p><strong>操作与记录：</strong> 记录单值还是范围、观察方向、接触状态、读数质量和重复稳定性。原始读数应保留，不要只记录一个经过四舍五入的“结论值”。</p><p><strong>结果解释：</strong> 将读数与候选的典型范围、双折射和样品状态一起比较；RI 只能支持或排除部分候选，不能单独证明天然、合成或处理状态。</p><p><strong>异常处理：</strong> 出现超出量程、边界模糊、接触不良或读数不稳定时，记录“无法可靠读数”和原因，改用适合样品的下一项非破坏性观察。</p><p><strong>风险/送检：</strong> 不为了得到名称而反复施压或污染样品；涉及高价值、正式披露或读数冲突时保留原始记录并送检。</p><h3 id="_2-比重-sg" tabindex="-1">2. 比重（SG） <a class="header-anchor" href="#_2-比重-sg" aria-label="Permalink to &quot;2. 比重（SG）&quot;">​</a></h3><p><strong>目的：</strong> 将质量与体积关系作为候选材料的补充证据。</p><p><strong>适用条件：</strong> 先判断样品是否适合液体或静水法。镶嵌、孔隙、吸液、表面损伤、极小样品或复合结构都可能使结果失真。</p><p><strong>操作与记录：</strong> 只按设备、液体和实验室安全说明操作，记录方法、样品状态、环境、重复结果、气泡/接触器具情况和必要修正。不要把未经检查的单次称重写成确定值。</p><p><strong>结果解释：</strong> SG 只能与 RI、光性、显微观察和候选范围交叉解释；单个 SG 数值不能直接等同于宝石名称。</p><p><strong>异常处理：</strong> 气泡、液体污染、样品吸液、接触器具干扰或重复结果差异明显时，标记结果不可靠，不继续用它排除候选。</p><p><strong>风险/送检：</strong> 液体、样品表面和废液按器材说明及安全数据处理；样品不适用或价值较高时跳过液体测试并考虑送检。</p><h3 id="_3-莫氏硬度" tabindex="-1">3. 莫氏硬度 <a class="header-anchor" href="#_3-莫氏硬度" aria-label="Permalink to &quot;3. 莫氏硬度&quot;">​</a></h3><p><strong>目的：</strong> 在明确授权和风险可接受时，记录相对刻划抗性。</p><p><strong>适用条件：</strong> 莫氏硬度不是第一选择。高价值、镶嵌、裂隙明显、易损或表面处理样品默认不做刻划测试。</p><p><strong>操作与记录：</strong> 若经授权实施，只记录测试位置、工具、方向和是否出现刻划现象；不能把“没有划痕”写成真品证明。</p><p><strong>结果解释：</strong> 莫氏硬度是相对刻划抗性，不等于真伪、耐久性、透明度或价值；不同操作者和表面状态也会影响观察。</p><p><strong>异常处理：</strong> 结果不清晰、样品表面已有损伤或工具状态不明时，记录“未获得可靠硬度结果”，不要重复施加损伤。</p><p><strong>风险/送检：</strong> 只要测试风险超过教育性筛分价值，就停止；正式鉴定和披露交给专业实验室。</p><h3 id="_4-解理与破裂风险" tabindex="-1">4. 解理与破裂风险 <a class="header-anchor" href="#_4-解理与破裂风险" aria-label="Permalink to &quot;4. 解理与破裂风险&quot;">​</a></h3><p><strong>目的：</strong> 识别结构性破裂风险，而不是主动制造破裂证据。</p><p><strong>适用条件：</strong> 根据已知矿物结构、外观裂隙和样品状态做风险记录；解理、断口、裂隙和已有损伤分开描述。</p><p><strong>操作与记录：</strong> 记录可见的方向性结构线索、既有损伤和不可测试原因，不通过敲击、劈开或强行施力验证解理。</p><p><strong>结果解释：</strong> 解理是结构性破裂倾向，不能默认它在成品外观上可见，也不能单独用于命名。</p><p><strong>异常处理：</strong> 结构风险不明确或样品出现松动、裂隙扩展迹象时，立即停止接触性测试并记录状态。</p><p><strong>风险/送检：</strong> 对钻石等存在明显破裂风险的样品，把解理作为停止信号，交给专业人员评估。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>折射率（RI）和比重（SG）应视为带条件的典型参考范围；方向、仪器、接触状态、处理和样品状态都会影响读数。</li><li>硬度是相对刻划抗性，不等于真伪、耐久性或价值；划痕测试可能损伤样品。</li><li>解理是结构性破裂倾向，不应通过敲击或劈开验证，也不应默认它在外观上可见。</li><li>任何读数都要与样品状态、重复结果和其他证据一起解释，不能脱离上下文比较。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>钻石</td><td>RI 2.42；SG 3.52</td><td>典型参考，需结合条件与其他证据</td></tr><tr><td>红宝石</td><td>RI 1.762–1.770；SG 4.00 ± 0.05</td><td>刚玉典型参考，不能单独命名</td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.gia.edu/gems-gemology/winter-2024-gemstone-analysis" target="_blank" rel="noreferrer">GIA：宝石实验室分析流程</a><span>标准宝石学测试、实验室工作流与实验室培育钻石分析示例</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2019-analytical-methods-geographic-origin-determination-gemstones" target="_blank" rel="noreferrer">GIA：宝石产地分析方法综述</a><span>RI/SG 作为鉴定起点，以及产地判断所需的后续分析</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/winter-2024-infrared-spectroscopy" target="_blank" rel="noreferrer">GIA：红外光谱在宝石学中的应用</a><span>光谱与原子结构、天然/合成/处理线索之间的关系</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/ruby" target="_blank" rel="noreferrer">GIA 宝石百科：红宝石</a><span>红宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/sapphire" target="_blank" rel="noreferrer">GIA 宝石百科：蓝宝石</a><span>蓝宝石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/emerald" target="_blank" rel="noreferrer">GIA 宝石百科：祖母绿</a><span>祖母绿的典型 RI、双折射、比重、硬度与处理/合成/仿品边界</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/spinel" target="_blank" rel="noreferrer">GIA 宝石百科：尖晶石</a><span>尖晶石的典型 RI、均质性、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/diamond" target="_blank" rel="noreferrer">GIA 宝石百科：钻石</a><span>钻石的典型 RI、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/zircon" target="_blank" rel="noreferrer">GIA 宝石百科：锆石</a><span>锆石的典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/articles/iolite-description" target="_blank" rel="noreferrer">GIA：堇青石（Iolite）描述</a><span>堇青石的强多色性与观察方向提示</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/tanzanite-description" target="_blank" rel="noreferrer">GIA：坦桑石描述</a><span>坦桑石的多色性、切磨方向、光源与热处理背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/peridot" target="_blank" rel="noreferrer">GIA 宝石百科：橄榄石</a><span>橄榄石典型 RI、双折射、比重和硬度参考</span><small>打开来源 ↗</small></li><li><a href="https://my.gia.edu/FAQ/gia-faq-two-green-garnet" target="_blank" rel="noreferrer">GIA FAQ：沙弗莱石与翠榴石的区别</a><span>绿色石榴石颜色重叠与矿物差异提示</span><small>打开来源 ↗</small></li></ul></aside><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',42)])])}const m=a(l,[["render",n]]);export{c as __pageData,m as default};
